namespace NovaHarvest.Core.Systems; public sealed class ProgressionSystem { readonly HashSet<string> _unlocks = new(); public IReadOnlyCollection<string> Unlocks => _unlocks; public bool Unlock(string id) => !string.IsNullOrWhiteSpace(id) && _unlocks.Add(id); public bool IsUnlocked(string id) => _unlocks.Contains(id); }
